import assert from 'node:assert/strict';
import {randomUUID} from 'node:crypto';
import type {Page} from 'playwright';
import type {PrismaClient} from '@prisma/client';
import {waitForBrowserJson} from './browser-poll';
export async function verifyRowGrain(page:Page,origin:string,workspaceId:string,db:PrismaClient,check:(page:Page,phase:string)=>Promise<void>){
 const name='Invoice grain browser '+randomUUID(),root=origin+'/dashboard/app/workspaces/'+workspaceId,api='/dashboard/app/api/workspaces/'+workspaceId;
 let datasetId:string|undefined;
 try{
  await page.goto(root+'/studio?create=1');await page.getByRole('region',{name:'Choose dashboard type',exact:true}).getByRole('button',{name:/^Sales performance\b/}).click();
  await page.getByLabel('Dataset name',{exact:true}).fill(name);await page.getByLabel('CSV, JSON or Excel file',{exact:true}).setInputFiles({name:'invoice-lines.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify([{invoice_id:'INV-A',line_id:'1',amount:50},{invoice_id:'INV-A',line_id:'2',amount:50},{invoice_id:'INV-B',line_id:'1',amount:25}]))});await page.getByRole('button',{name:'Upload and profile dataset',exact:true}).click();
  const result=await waitForBrowserJson<{datasets:{id:string;name:string;status:string;grainSuggestion?:{kind:string;confirmationRequired:boolean};metricRules:unknown}[]}>(page,api+'/datasets',r=>r.datasets.some(d=>d.name===name&&d.status==='READY'),'Invoice line profiling');const dataset=result.datasets.find(d=>d.name===name)!;datasetId=dataset.id;assert.equal(dataset.grainSuggestion?.kind,'INVOICE_ITEM');assert.equal(dataset.grainSuggestion?.confirmationRequired,true);assert.equal(dataset.metricRules,null);
  await page.getByLabel('Dataset for a new dashboard',{exact:true}).selectOption({label:name});
  await page.getByText('Review suggested field meanings (not yet confirmed)',{exact:true}).click();for(const [field,concept] of [['invoice_id','INVOICE'],['line_id','LINE_ITEM'],['amount','REVENUE']])await page.getByLabel('Meaning of '+field,{exact:true}).selectOption(concept);await page.getByRole('button',{name:'Save confirmed field meanings',exact:true}).click();await page.getByText('Field choices saved.',{exact:false}).waitFor();
  await page.getByText('Confirm business calculation rules',{exact:true}).click();await page.getByRole('region',{name:'Suggested row meaning',exact:true}).getByRole('heading',{name:'Suggested row meaning: INVOICE ITEM',exact:true}).waitFor();assert.equal(await page.getByLabel('What does one row represent?',{exact:true}).inputValue(),'');
  for(const [label,value] of [['What does one row represent?','INVOICE_ITEM'],['Currency structure','SINGLE'],['Revenue basis','NET'],['Cost basis','COGS'],['Refunds already included in revenue?','true'],['Discounts already included in revenue?','true'],['Tax already included in revenue?','false'],['Shipping already included in revenue?','false'],['Cancelled orders','ALREADY_EXCLUDED'],['Returned units','ALREADY_NETTED']])await page.getByLabel(label,{exact:true}).selectOption(value);
  await page.getByLabel('Three-letter currency code',{exact:true}).fill('USD');
  const amountLabel='All monetary inputs are per line, not repeated document totals (line-item data)';
  async function save(){await page.getByRole('button',{name:'Save business rules',exact:true}).click();await page.getByText('Business rules saved.',{exact:false}).waitFor();await page.getByRole('button',{name:'Calculate metrics',exact:true}).click();}
  type Analysis={analysis:{outcomes:{key:string;status:string;value:number|null;reason:string|null}[]}|null};
  await save();const before=await waitForBrowserJson<Analysis>(page,api+'/datasets/'+datasetId+'/analysis',r=>r.analysis?.outcomes.some(m=>m.key==='REVENUE'&&m.status==='NEEDS_CONFIRMATION')===true,'Line amount confirmation guard');assert.equal(before.analysis?.outcomes.find(m=>m.key==='REVENUE')?.value,null);await page.getByRole('region',{name:'Metric results table',exact:true}).getByText('Confirm that all monetary inputs, including refunds and discounts, are amounts per line, not repeated document totals.',{exact:true}).first().waitFor();await check(page,'invoice-line-confirmation-guard');
  await page.getByLabel(amountLabel,{exact:true}).selectOption('true');await save();const after=await waitForBrowserJson<Analysis>(page,api+'/datasets/'+datasetId+'/analysis',r=>r.analysis?.outcomes.some(m=>m.key==='REVENUE'&&m.status==='READY')===true,'Confirmed line revenue');assert.equal(after.analysis?.outcomes.find(m=>m.key==='REVENUE')?.value,125);assert.equal(after.analysis?.outcomes.find(m=>m.key==='ORDERS')?.value,null);await page.getByRole('region',{name:'Metric results table',exact:true}).getByRole('row').filter({has:page.getByRole('rowheader',{name:'Revenue',exact:true})}).getByRole('cell',{name:'125',exact:true}).waitFor();await check(page,'confirmed-invoice-line-grain');
  await page.setViewportSize({width:390,height:844});await check(page,'invoice-line-grain-mobile');assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));
  console.log('PASS: real invoice-line upload/profile, persisted advisory-only grain, explicit field/grain/amount confirmation, refusal before consent, revenue 125, no invented orders, desktop/mobile accessibility.');
 }finally{await page.setViewportSize({width:1280,height:900});if(datasetId){await db.dashboardDataset.deleteMany({where:{id:datasetId,workspaceId}});await db.dashboardDataSource.deleteMany({where:{workspaceId,name}});}await page.goto(root+'/studio');}
}
